using TownOfHost;using TownOfHost.Modules;using TownOfHost.Roles.Core;using TownOfHost.Roles.Core.Interfaces;using System.Text.Json.Nodes;
class Killer:IKiller{}
class Program{static int passed;static void Check(bool b,string m="assertion"){if(!b)throw new Exception(m);}static void Test(string n,Action a){Utils.Sent.Clear();a();passed++;Console.WriteLine("PASS "+n);}static void Fresh(){AmongUsClient.Instance=new();GameModeManager.Standard=true;CustomWinnerHolder.WinnerTeam=CustomWinner.Crewmate;CustomWinnerHolder.WinnerIds.Clear();TownOfHost.Main.winnerList.Clear();PlayerState.AllPlayerStates.Clear();TownOfHost.Main.AllPlayerNames.Clear();}
static void Main(){TownOfHost.Main.BaseDirectory=Path.Combine(Path.GetTempPath(),"TOHS-Stats-Tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(TownOfHost.Main.BaseDirectory);
Test("time notices default OFF",()=>{MeetingTimeAnnounce.Enabled=null;MeetingTimeAnnounce.Postfix(new(){discussionTimer=45});Check(Utils.Sent.Count==0);});
MeetingTimeAnnounce.Enabled=new(){Value=true};
Test("30 and 10 seconds each exactly once",()=>{var h=new MeetingHud();foreach(var t in new[]{15f,44.5f,45.2f,45.9f,46.2f,64.2f,65.1f,65.9f,70f}){h.discussionTimer=t;MeetingTimeAnnounce.Postfix(h);}Check(Utils.Sent.Count==2&&Utils.Sent[0].Text.Contains("30秒")&&Utils.Sent[1].Text.Contains("10秒"));});
Test("frame jump across mark still notifies",()=>{var h=new MeetingHud{discussionTimer=42};MeetingTimeAnnounce.Postfix(h);h.discussionTimer=47;MeetingTimeAnnounce.Postfix(h);Check(Utils.Sent.Count==1&&Utils.Sent[0].Text.Contains("30秒"));});
Test("short meeting skips 30s mark",()=>{TownOfHost.Main.NormalOptions.VotingTime=20;var h=new MeetingHud{discussionTimer=16};MeetingTimeAnnounce.Postfix(h);h.discussionTimer=26;MeetingTimeAnnounce.Postfix(h);Check(Utils.Sent.Count==1&&Utils.Sent[0].Text.Contains("10秒"));TownOfHost.Main.NormalOptions.VotingTime=60;});
Test("no notice after time zero or exile",()=>{GameStates.ExiledAnimate=true;MeetingTimeAnnounce.Postfix(new(){discussionTimer=45});GameStates.ExiledAnimate=false;MeetingTimeAnnounce.Postfix(new(){discussionTimer=80});Check(Utils.Sent.Count==0);});
Test("nonhost does not announce",()=>{AmongUsClient.Instance.AmHost=false;MeetingTimeAnnounce.Postfix(new(){discussionTimer=45});Check(Utils.Sent.Count==0);AmongUsClient.Instance.AmHost=true;});
Test("unlimited voting has no notices",()=>{TownOfHost.Main.NormalOptions.VotingTime=0;MeetingTimeAnnounce.Postfix(new());Check(Utils.Sent.Count==0);TownOfHost.Main.NormalOptions.VotingTime=60;});
Fresh();PlayerState.AllPlayerStates[1]=new(){MainRole=CustomRoles.Crewmate};PlayerState.AllPlayerStates[2]=new(){MainRole=CustomRoles.Impostor};TownOfHost.Main.winnerList.Add(1);
Test("stats default OFF does not write",()=>{RoleWinStats.Enabled=null;RoleWinStats.OnGameEnd();Check(!File.Exists(Path.Combine(TownOfHost.Main.BaseDirectory,"RoleWinStats.json")));});RoleWinStats.Enabled=new(){Value=true};
Test("stats records final winner list not raw winner IDs",()=>{RoleWinStats.OnGameEnd();var n=JsonNode.Parse(File.ReadAllText(Path.Combine(TownOfHost.Main.BaseDirectory,"RoleWinStats.json")));Check(n["Crewmate"]["Wins"].GetValue<int>()==1&&n["Impostor"]["Wins"].GetValue<int>()==0);});
Test("stats rankings and private recipient",()=>{RoleWinStats.OnGameEnd();RoleWinStats.OnGameEnd();Check(RoleWinStats.TryHandle("/stats",7)&&Utils.Sent.Single().To==7&&Utils.Sent[0].Text.Contains("100%"));});
Test("individual role query",()=>{Check(RoleWinStats.TryHandle("/cmd stats Impostor",8)&&Utils.Sent.Single().Text.Contains("0%"));});
Test("unrelated command not intercepted",()=>Check(!RoleWinStats.TryHandle("/cmd kick 1",8)));
Test("stats nonhost refuses host execution",()=>{AmongUsClient.Instance.AmHost=false;Check(!RoleWinStats.TryHandle("/stats",8));AmongUsClient.Instance.AmHost=true;});
Test("draw does not increment statistics",()=>{CustomWinnerHolder.WinnerTeam=CustomWinner.Draw;RoleWinStats.OnGameEnd();CustomWinnerHolder.WinnerTeam=CustomWinner.Crewmate;RoleWinStats.TryHandle("/stats Crewmate",8);Check(Utils.Sent.Single().Text.Contains("(3/3)"));});
Test("custom modes do not increment statistics",()=>{GameModeManager.Standard=false;RoleWinStats.OnGameEnd();GameModeManager.Standard=true;RoleWinStats.TryHandle("/stats Crewmate",8);Check(Utils.Sent.Single().Text.Contains("(3/3)"));});
Fresh();TownOfHost.Main.AllPlayerNames[1]="Crew";TownOfHost.Main.AllPlayerNames[2]="Imp";PlayerState.AllPlayerStates[1]=new(){MainRole=CustomRoles.Crewmate,taskState=new(){hasTasks=true,AllTasksCount=5,CompletedTasksCount=5}};PlayerState.AllPlayerStates[2]=new(){MainRole=CustomRoles.Impostor,Kills=1};TownOfHost.Main.winnerList.Add(1);
Test("MVP default OFF",()=>{MvpAnnouncer.Enabled=null;MvpAnnouncer.OnGameEnd();Check(Utils.Sent.Count==0);});MvpAnnouncer.Enabled=new(){Value=true};
Test("MVP votes tasks win alive score",()=>{MvpAnnouncer.OnMeetingEnd(new[]{((byte)1,(byte)2)});MvpAnnouncer.OnGameEnd();Check(Utils.Sent.Single().Text.Contains("Crew")&&Utils.Sent[0].Text.Contains("正しい投票1"));});
Test("MVP votes reset between games",()=>{MvpAnnouncer.OnGameEnd();Check(!Utils.Sent.Single().Text.Contains("正しい投票"));});
Test("MVP draw excluded",()=>{CustomWinnerHolder.WinnerTeam=CustomWinner.Draw;MvpAnnouncer.OnGameEnd();Check(Utils.Sent.Count==0);CustomWinnerHolder.WinnerTeam=CustomWinner.Crewmate;});
Test("MVP custom modes excluded",()=>{GameModeManager.Standard=false;MvpAnnouncer.OnGameEnd();Check(Utils.Sent.Count==0);GameModeManager.Standard=true;});
Test("MVP not sent by nonhost",()=>{AmongUsClient.Instance.AmHost=false;MvpAnnouncer.OnGameEnd();Check(Utils.Sent.Count==0);AmongUsClient.Instance.AmHost=true;});
PlayerControl a=new PlayerControl{PlayerId=1,Data=new(){FriendCode="synthetic-a",PlayerName="A"}},b=new PlayerControl{PlayerId=2,Data=new(){FriendCode="synthetic-b",PlayerName="B"}};var candidates=new List<PlayerControl>{a,b};PlayerControl.AllPlayerControls=new(){a,b};
Test("repeat avoidance OFF preserves RNG",()=>{RoleRepeatAvoid.Enabled=null;Check(RoleRepeatAvoid.Pick(candidates,CustomRoles.Crewmate,new())==a);});
Test("repeat avoidance chooses eligible fresh player",()=>{RoleRepeatAvoid.OnGameEnd();RoleRepeatAvoid.Enabled=new(){Value=true};Check(RoleRepeatAvoid.Pick(candidates,CustomRoles.Crewmate,new())==b);});
Test("repeat avoidance retains fallback when all recent",()=>{PlayerState.AllPlayerStates[2].MainRole=CustomRoles.Crewmate;RoleRepeatAvoid.OnGameEnd();Check(RoleRepeatAvoid.Pick(candidates,CustomRoles.Crewmate,new())==a);});
Test("initial cooldown ignores non killers",()=>{Options.CustomRoleSpawnChances[CustomRoles.Locksmith]=new();InitialKillCooldownOption.Create(new(){ClassType=typeof(Program),RoleName=CustomRoles.Locksmith});Check(OptionItem.AllOptions.Count==0);});
Test("initial cooldown uses stable role ID despite shared ConfigId",()=>{foreach(var r in new[]{CustomRoles.StepBomber,CustomRoles.Impostor}){Options.CustomRoleSpawnChances[r]=new();InitialKillCooldownOption.Create(new(){ClassType=typeof(Killer),RoleName=r,ConfigId=1});}Check(OptionItem.AllOptions.Select(o=>o.Id).Distinct().Count()==2&&OptionItem.AllOptions.All(o=>o.Id>=8000000));});
Test("initial cooldown zero keeps previous default",()=>Check(InitialKillCooldownOption.Resolve(new(){Role=CustomRoles.StepBomber},10)==10));
Test("initial cooldown explicit value applies",()=>{OptionItem.AllOptions.Single(o=>o.Id==8000370).Float=25;Check(InitialKillCooldownOption.Resolve(new(){Role=CustomRoles.StepBomber},10)==25);});
Test("initial cooldown duplicate registration ignored",()=>{InitialKillCooldownOption.Create(new(){ClassType=typeof(Killer),RoleName=CustomRoles.StepBomber});Check(OptionItem.AllOptions.Count==2);});
Console.WriteLine($"RESULT {passed} passed, 0 failed (actual modules, game substitutes)");}}
